<script setup>
import {ref,computed} from 'vue';import {state} from '../lib/workspace';
const props=defineProps({modelValue:{type:Array,default:()=>[]},catalog:{type:Object,required:true},companyIds:{type:Array,default:null},individual:Boolean});const emit=defineEmits(['update:modelValue']);
const cid=ref(''),module=ref('fiscal');const companies=computed(()=>state.companies.filter(c=>!props.companyIds||props.companyIds.includes(c.id)));const selected=computed(()=>Number(cid.value||companies.value[0]?.id));const routines=computed(()=>props.catalog.routines.filter(r=>r.module===module.value));
function value(r,a){return props.modelValue.find(p=>p.company_id===selected.value&&p.routine===r&&p.action===a)?.effect||'';}
function set(r,a,e){const list=props.modelValue.filter(p=>!(p.company_id===selected.value&&p.routine===r&&p.action===a));if(e)list.push({company_id:selected.value,routine:r,action:a,effect:e});emit('update:modelValue',list);}
function bulk(effect){let list=props.modelValue.filter(p=>!(p.company_id===selected.value&&(p.routine===module.value+'.*'||routines.value.some(r=>r.id===p.routine))));if(effect)for(const r of routines.value)for(const action of r.actions)list.push({company_id:selected.value,routine:r.id,action,effect});emit('update:modelValue',list);}
const special=computed(()=>props.modelValue.filter(p=>p.company_id===selected.value&&(p.routine.includes('*')||p.action==='*')));
</script>
<template><section><div class="form-grid"><label>Permissões na empresa<select v-model="cid" :disabled="!companies.length"><option value="" disabled>Selecione (padrão: primeira empresa)</option><option v-for="c in companies" :key="c.id" :value="c.id">{{c.code}} · {{c.name}}</option></select></label><label>Módulo<select v-model="module"><option v-for="(label,id) in catalog.modules" :value="id" :key="id">{{label}}</option></select></label></div><p v-if="!companies.length" class="message warning">Selecione uma empresa para configurar suas rotinas.</p><template v-else><p class="field-help">Empresa em edição: <strong>{{companies.find(c=>c.id===selected)?.name}}</strong>. {{individual?'Herdar mantém os grupos. Negar individual prevalece sobre permitir individual; permitir individual prevalece sobre decisões dos grupos.':'Sem concessão não libera a rotina. Havendo conflitos entre grupos, negar prevalece.'}}</p><div class="actions"><button type="button" class="button small" @click="bulk('allow')">Permitir módulo</button><button type="button" class="button small" @click="bulk('deny')">Bloquear módulo</button><button type="button" class="button small" @click="bulk('')">{{individual?'Herdar módulo':'Limpar módulo'}}</button></div><div v-if="special.length" class="message warning"><p>Regras abrangentes existentes também participam do resultado:</p><div v-for="p in special" :key="p.routine+p.action">{{p.routine}} / {{p.action}}: {{p.effect==='deny'?'Negar':'Permitir'}} <button type="button" class="text-button" @click="set(p.routine,p.action,'')">Remover regra</button></div></div><div class="table-scroll permission-matrix"><table><thead><tr><th>Rotina</th><th v-for="(label,a) in catalog.actions" :key="a">{{label}}</th></tr></thead><tbody><tr v-for="r in routines" :key="r.id"><th>{{r.name}}</th><td v-for="(_,a) in catalog.actions" :key="a"><select v-if="r.actions.includes(a)" :value="value(r.id,a)" @change="set(r.id,a,$event.target.value)" :aria-label="`${r.name}: ${catalog.actions[a]}`" :class="value(r.id,a)"><option value="">{{individual?'Herdar':'—'}}</option><option value="allow">Permitir</option><option value="deny">Negar</option></select><span v-else>—</span></td></tr></tbody></table></div></template></section></template>
<style scoped>.permission-matrix{margin-top:12px}.permission-matrix th{white-space:normal;min-width:95px}.permission-matrix th:first-child{min-width:180px}.permission-matrix select{min-width:88px;font-size:12px;padding:5px}.allow{color:#176253;background:#eef8f3}.deny{color:#a32929;background:#fff2f1}</style>
